1	/**
2	 * cf-extra-routes.ts — barrel for CF-native route modules.
3	 *
4	 * CF-native handlers for API endpoints that use raw Express handlers in the
5	 * server package (making them invisible to extractRoutesFromRouter) or depend
6	 * on runtime registries (adapters, plugins) that don't exist in a CF Worker.
7	 *
8	 * Registered in app.ts BEFORE the /api/* catch-all so they shadow the 501.
9	 *
10	 * Modules:
11	 *   routes/adapters.ts       — GET /api/adapters
12	 *   routes/plugins.ts        — GET /api/plugins, GET /api/plugins/ui-contributions
13	 *   routes/company-access.ts — GET /api/companies/:id/join-requests,
14	 *                               GET /api/companies/:id/user-directory
15	 *   routes/company-skills-cf.ts — GET /api/companies/:id/skills
16	 *   routes/events.ts         — GET /api/companies/:id/events/ws
17	 *
18	 * All routes in this barrel require an authenticated actor (board or agent key,
19	 * or local_trusted mode). Unauthenticated requests receive 401.
20	 */
21	
22	import type { Hono } from "hono";
23	import type { Env } from "./env.js";
24	import { registerAdapterRoutes } from "./routes/adapters.js";
25	import { registerPluginRoutes } from "./routes/plugins.js";
26	import { registerCompanyAccessRoutes } from "./routes/company-access.js";
27	import { registerCompanySkillRoutes } from "./routes/company-skills-cf.js";
28	import { registerEventRoutes } from "./routes/events.js";
29	
30	export function registerCfExtraRoutes(app: Hono<{ Bindings: Env }>): void {
31	  registerAdapterRoutes(app);
32	  registerPluginRoutes(app);
33	  registerCompanyAccessRoutes(app);
34	  registerCompanySkillRoutes(app);
35	  registerEventRoutes(app);
36	}
